#![forbid(unsafe_code)]
//! Stable, pointer-free Swift/Kotlin API generated by UniFFI.

use messenger_core::{CachedRelayDirectory, IncomingEvent, MessengerCore, NetworkMode};
use messenger_crypto::{CryptoEngine, IncomingMessage, MemberCredential};
use std::sync::Mutex;
use thiserror::Error;

#[derive(Debug, Error, uniffi::Error)]
pub enum FfiError {
    #[error("invalid input")]
    InvalidInput,
    #[error("cryptographic operation failed")]
    Crypto,
    #[error("local storage operation failed")]
    Storage,
}

#[uniffi::export]
pub fn protocol_round_trip(frame: Vec<u8>) -> Result<Vec<u8>, FfiError> {
    let decoded =
        messenger_protocol::TransportFrame::decode(&frame).map_err(|_| FfiError::InvalidInput)?;
    decoded.encode().map_err(|_| FfiError::InvalidInput)
}

#[derive(Clone, uniffi::Record)]
pub struct FfiMemberCredential {
    pub device_id: Vec<u8>,
    pub account_id: Vec<u8>,
    pub certificate_fingerprint: Vec<u8>,
}

