#[uniffi::export]
impl MlsDevice {
    #[uniffi::constructor]
    pub fn initialize_crypto_store(
        member: FfiMemberCredential,
        state_key: Vec<u8>,
    ) -> Result<Self, FfiError> {
        let state_key = state_key.try_into().map_err(|_| FfiError::InvalidInput)?;
        let engine = CryptoEngine::initialize_crypto_store(member.try_into()?, state_key)
            .map_err(|_| FfiError::Crypto)?;
        Ok(Self {
            engine: Mutex::new(engine),
        })
    }

    pub fn generate_key_packages(&self, count: u32) -> Result<Vec<Vec<u8>>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .generate_key_packages(count as usize)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn export_public_key_packages(&self, count: u32) -> Result<Vec<Vec<u8>>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .export_public_key_packages(count as usize)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn create_conversation(&self, group_id: Vec<u8>) -> Result<(), FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .create_conversation(&group_id)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn commit_add_member(
        &self,
        group_id: Vec<u8>,
        key_package: Vec<u8>,
    ) -> Result<Vec<Vec<u8>>, FfiError> {
        let change = self
            .engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .commit_add_members(&group_id, &[key_package])
            .map_err(|_| FfiError::Crypto)?;
        Ok(vec![change.commit, change.welcome.unwrap_or_default()])
    }

    pub fn propose_add_member(
        &self,
        group_id: Vec<u8>,
        key_package: Vec<u8>,
    ) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .propose_add_members(&group_id, &key_package)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn commit_remove_member(
        &self,
        group_id: Vec<u8>,
        member: FfiMemberCredential,
    ) -> Result<Vec<Vec<u8>>, FfiError> {
        let change = self
            .engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .commit_remove_members(&group_id, &member.try_into()?)
            .map_err(|_| FfiError::Crypto)?;
        Ok(vec![change.commit, change.welcome.unwrap_or_default()])
    }

    pub fn propose_remove_member(
        &self,
        group_id: Vec<u8>,
        member: FfiMemberCredential,
    ) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .propose_remove_members(&group_id, &member.try_into()?)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn join_conversation_from_welcome(&self, welcome: Vec<u8>) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .join_conversation_from_welcome(&welcome)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn encrypt_application_message(
        &self,
        group_id: Vec<u8>,
        plaintext: Vec<u8>,
    ) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .encrypt_application_message(&group_id, &plaintext)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn process_incoming_message(
        &self,
        group_id: Vec<u8>,
        ciphertext: Vec<u8>,
    ) -> Result<Vec<u8>, FfiError> {
        match self
            .engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .process_incoming_message(&group_id, &ciphertext)
            .map_err(|_| FfiError::Crypto)?
        {
            IncomingMessage::Application(value) => Ok(value),
            _ => Ok(Vec::new()),
        }
    }

    pub fn export_conversation_state(&self, group_id: Vec<u8>) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .export_conversation_state(&group_id)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn import_conversation_state(&self, snapshot: Vec<u8>) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .import_conversation_state(&snapshot)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn get_conversation_epoch(&self, group_id: Vec<u8>) -> Result<u64, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .get_conversation_epoch(&group_id)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn self_update(&self, group_id: Vec<u8>) -> Result<Vec<u8>, FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .self_update(&group_id)
            .map_err(|_| FfiError::Crypto)
    }

    pub fn verify_member_credential(
        &self,
        encoded: Vec<u8>,
        root_public_key: Vec<u8>,
        certificate: FfiDeviceCertificate,
    ) -> Result<FfiMemberCredential, FfiError> {
        let root_public_key = root_public_key
            .try_into()
            .map_err(|_| FfiError::InvalidInput)?;
        let certificate = messenger_identity::DeviceCertificate {
            device_id: certificate
                .device_id
                .try_into()
                .map_err(|_| FfiError::InvalidInput)?,
            device_public_key: certificate
                .device_public_key
                .try_into()
                .map_err(|_| FfiError::InvalidInput)?,
            issued_at: certificate.issued_at,
            signature: certificate
                .signature
                .try_into()
                .map_err(|_| FfiError::InvalidInput)?,
        };
        let member = self
            .engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .verify_member_credential(&encoded, &root_public_key, &certificate)
            .map_err(|_| FfiError::Crypto)?;
        Ok(FfiMemberCredential {
            device_id: member.device_id.to_vec(),
            account_id: member.account_id.to_vec(),
            certificate_fingerprint: member.certificate_fingerprint.to_vec(),
        })
    }

    pub fn destroy_local_conversation_state(&self, group_id: Vec<u8>) -> Result<(), FfiError> {
        self.engine
            .lock()
            .map_err(|_| FfiError::Crypto)?
            .destroy_local_conversation_state(&group_id)
            .map_err(|_| FfiError::Crypto)
    }
}

uniffi::setup_scaffolding!();

#[cfg(test)]
mod tests {
    use super::*;
    fn member(seed: u8) -> FfiMemberCredential {
        FfiMemberCredential {
            device_id: vec![seed; 16],
            account_id: vec![seed; 32],
            certificate_fingerprint: vec![seed; 16],
        }
    }
    #[test]
    fn ffi_surface_calls_real_openmls() {
        let alice = MlsDevice::initialize_crypto_store(member(1), vec![1; 32]).unwrap();
        let bob = MlsDevice::initialize_crypto_store(member(2), vec![2; 32]).unwrap();
        let package = bob.generate_key_packages(1).unwrap().remove(0);
        alice.create_conversation(b"ffi-test".to_vec()).unwrap();
        let change = alice
            .commit_add_member(b"ffi-test".to_vec(), package)
            .unwrap();
        bob.join_conversation_from_welcome(change[1].clone())
            .unwrap();
        let encrypted = alice
            .encrypt_application_message(b"ffi-test".to_vec(), b"real MLS".to_vec())
            .unwrap();
        assert_eq!(
            bob.process_incoming_message(b"ffi-test".to_vec(), encrypted)
                .unwrap(),
            b"real MLS"
        );
        let ping = hex("8601010e50070707070707070707070707070707070040");
        assert_eq!(protocol_round_trip(ping.clone()).unwrap(), ping);
    }
    fn hex(value: &str) -> Vec<u8> {
        (0..value.len())
            .step_by(2)
            .map(|index| u8::from_str_radix(&value[index..index + 2], 16).unwrap())
            .collect()
    }
}
